  <div class="hero-visual"><div class="orbit-caption">THE ROUTE</div>${flowItems.map(([type,label],i)=>`<div class="hero-stop stop-${i+1}"><span>${icon(type)}</span><b>${label}</b></div>`).join('')}<div class="hero-route"><i></i></div><div class="hero-badge">12 proposed instances<br><strong>1 writer decides</strong></div></div>
</section>
